		{
			var result = base.ShowPreSaveDialogs();

			if (result == ContinueWithSave.Yes && Row.IsFirstPackingStationLocationInThisWarehouse())
			{
				var warningText = Res.GetString("9e66c2bb-c7c5-40b8-ac2c-88f8d132cca5", "This is the first Packing Station location for this warehouse. Once saved, all Tote/Trolley jobs must be put away at the Packing Station before proceeding to the Dock Door. Do you wish to enable Packing Stations in this Warehouse?");
				var messageResult = Globals.Message.Show(warningText, Res.GetString("dd167f4e-694b-49ac-a962-c9326ba85899", "Save"), MessageBoxButtons.YesNo, MessageBoxIcon.Question, DialogResult.Yes);
				result = messageResult == DialogResult.Yes ? ContinueWithSave.Yes : ContinueWithSave.No;
			}

			return result;
		}


